import { useState } from 'react';
import {
  JxStepper,
  JxInputField,
  JxTextareaField,
  JxButton,
  JxDivider,
  JxSnip,
} from '@jinx-ui/react';

interface RegistrationFormProps {
  onSubmit: (data: {
    fullName: string;
    email: string;
    phone: string;
    address: string;
    city: string;
    postalCode: string;
  }) => void;
}

const steps = [{ label: 'Контакты' }, { label: 'Адрес' }, { label: 'Проверка' }];

export default function RegistrationForm({ onSubmit }: RegistrationFormProps) {
  const [step, setStep] = useState(0);
  const [fullName, setFullName] = useState('');
  const [email, setEmail] = useState('');
  const [phone, setPhone] = useState('');
  const [address, setAddress] = useState('');
  const [city, setCity] = useState('');
  const [postalCode, setPostalCode] = useState('');

  const isContactsValid = fullName.trim().length > 0 && email.includes('@');
  const isAddressValid = address.trim().length > 0 && city.trim().length > 0;

  const canGoNext = step === 0 ? isContactsValid : step === 1 ? isAddressValid : true;

  const goBack = () => setStep((current) => Math.max(current - 1, 0));
  const goNext = () => setStep((current) => Math.min(current + 1, steps.length - 1));

  const handleSubmit = () => {
    onSubmit({ fullName, email, phone, address, city, postalCode });
  };

  return (
    <div
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: '20px',
        maxWidth: '480px',
        padding: '24px',
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <JxStepper steps={steps} current={step} />

      {step === 0 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxInputField
            label="Полное имя"
            required
            value={fullName}
            onChange={(event) => setFullName(event.target.value)}
          />
          <JxInputField
            label="Электронная почта"
            type="email"
            required
            value={email}
            onChange={(event) => setEmail(event.target.value)}
            errorText={email.length > 0 && !email.includes('@') ? 'Укажите адрес с символом @' : undefined}
          />
          <JxInputField
            label="Телефон"
            type="tel"
            prefix="+7"
            value={phone}
            onChange={(event) => setPhone(event.target.value)}
          />
        </div>
      )}

      {step === 1 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
          <JxTextareaField
            label="Адрес"
            required
            rows={3}
            value={address}
            onChange={(event) => setAddress(event.target.value)}
          />
          <JxInputField
            label="Город"
            required
            value={city}
            onChange={(event) => setCity(event.target.value)}
          />
          <JxInputField
            label="Почтовый индекс"
            value={postalCode}
            onChange={(event) => setPostalCode(event.target.value)}
          />
        </div>
      )}

      {step === 2 && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '10px' }}>
          <div>
            <div style={{ color: 'var(--jx-text-3)', fontSize: '13px' }}>Полное имя</div>
            <JxSnip>{fullName || '—'}</JxSnip>
          </div>
          <div>
            <div style={{ color: 'var(--jx-text-3)', fontSize: '13px' }}>Электронная почта</div>
            <JxSnip>{email || '—'}</JxSnip>
          </div>
          <div>
            <div style={{ color: 'var(--jx-text-3)', fontSize: '13px' }}>Телефон</div>
            <JxSnip>{phone || '—'}</JxSnip>
          </div>
          <JxDivider />
          <div>
            <div style={{ color: 'var(--jx-text-3)', fontSize: '13px' }}>Адрес</div>
            <JxSnip>{address || '—'}</JxSnip>
          </div>
          <div>
            <div style={{ color: 'var(--jx-text-3)', fontSize: '13px' }}>Город</div>
            <JxSnip>{city || '—'}</JxSnip>
          </div>
          <div>
            <div style={{ color: 'var(--jx-text-3)', fontSize: '13px' }}>Почтовый индекс</div>
            <JxSnip>{postalCode || '—'}</JxSnip>
          </div>
        </div>
      )}

      <div style={{ display: 'flex', justifyContent: 'space-between', gap: '8px' }}>
        <JxButton variant="ghost" disabled={step === 0} onClick={goBack}>
          Назад
        </JxButton>
        {step < steps.length - 1 ? (
          <JxButton variant="primary" disabled={!canGoNext} onClick={goNext}>
            Дальше
          </JxButton>
        ) : (
          <JxButton variant="primary" onClick={handleSubmit}>
            Отправить
          </JxButton>
        )}
      </div>
    </div>
  );
}

